"""Add ``[source]`` links to MATLAB domain objects, viewcode-style.

Generated by Claude Opus 5 and fixed by a human.

A version-independent replacement for ``sphinx.ext.linkcode``/``viewcode`` for
the ``mat`` domain, for Sphinx versions without ``add_linkcode_domain``
(added in 8.2).

Every ``.m`` file under ``matlab_src_dir`` is indexed at startup and rendered
as a syntax-highlighted page under a subfolder of the HTML output, and each
documented object links to its own line on that page.

Enable in conf.py::

    import os, sys
    sys.path.insert(0, os.path.abspath("_ext"))
    extensions = [..., "matlab_sourcelinks"]

    matlab_source_subdir = "_matlabsrc"   # optional, this is the default
"""

import os
import posixpath
import re

from docutils import nodes
from sphinx import addnodes
from sphinx.errors import NoUri
from sphinx.util import logging

logger = logging.getLogger(__name__)

_INDEX = {}  # file stem -> [relative posix paths]
_ROOT = None  # absolute path of matlab_src_dir


def _strip(token):
    """'+pkg' and '@Widget' both name the plain identifier."""
    return token.lstrip("+@")


def _build_index(app):
    global _ROOT
    _INDEX.clear()
    src_dir = app.config.matlab_src_dir
    if not src_dir:
        return
    _ROOT = os.path.join(app.confdir, src_dir)
    for dirpath, _dirnames, filenames in os.walk(_ROOT):
        for name in filenames:
            if not name.endswith(".m"):
                continue
            rel = os.path.relpath(os.path.join(dirpath, name), _ROOT)
            _INDEX.setdefault(name[:-2], []).append(rel.replace(os.sep, "/"))
    logger.info("[matlab-src] indexed %d MATLAB files", sum(map(len, _INDEX.values())))


def _score(rel, module, cls):
    """Rank a candidate by how well its directories match the object."""
    want = [_strip(t) for t in (module or "").split(".") if t]
    have = [_strip(t) for t in posixpath.dirname(rel).split("/") if t]
    score = 0
    # Reward matching trailing directory components.
    for a, b in zip(reversed(want), reversed(have)):
        if a != b:
            break
        score += 2
    # A method should prefer a file sitting in its own class's @-folder.
    if cls and have and have[-1] == _strip(cls):
        score += 3
    return score


def _lookup(stem, module, cls):
    paths = _INDEX.get(stem)
    if not paths:
        return None
    return max(paths, key=lambda rel: _score(rel, module, cls))


def _resolve(signode):
    """Return (relative .m path, name to anchor on) for a signature node."""
    fullname = signode.get("fullname") or ""
    if not fullname:
        return None, None
    module = signode.get("module") or ""
    cls = signode.get("class") or ""
    name = fullname.rsplit(".", 1)[-1]

    # 1. A method defined in the body of its class's file.
    if cls:
        return _lookup(_strip(cls).split(".")[-1], module, cls), name

    # 2. The object's own file: a free function, a class, or a method that
    #    lives in its own file inside an @-folder.
    own = _lookup(name, module, cls)
    if own:
        return own, name
    return None, None


def _read(rel):
    path = os.path.join(_ROOT, *rel.split("/"))
    with open(path, encoding="utf-8", errors="replace") as fh:
        return fh.read()


def _lineno(rel, name):
    """Line number of the function/classdef that defines `name`, if found."""
    pattern = re.compile(r"^\s*(?:function|classdef)\b[^%\n]*?\b" + re.escape(name) + r"\b")
    try:
        for i, line in enumerate(_read(rel).splitlines(), 1):
            if pattern.match(line):
                return i
    except OSError:
        pass
    return None


def _pagename(app, rel):
    return posixpath.join(app.config.matlab_source_subdir, rel[:-2])


def _add_source_links(app, doctree):
    for objnode in list(doctree.findall(addnodes.desc)):
        if objnode.get("domain") != "mat":
            continue
        for signode in objnode:
            if not isinstance(signode, addnodes.desc_signature):
                continue
            rel, name = _resolve(signode)
            if not rel:
                logger.debug(
                    "[matlab-src] no file for module=%r class=%r fullname=%r",
                    signode.get("module"),
                    signode.get("class"),
                    signode.get("fullname"),
                )
                continue
            line = _lineno(rel, name)
            inline = nodes.inline("", "[source]", classes=["viewcode-link"])
            xref = addnodes.pending_xref(
                "",
                inline,
                reftype="matsource",
                refdomain="std",
                refexplicit=False,
                reftarget=_pagename(app, rel),
                refid=f"L-{line}" if line else "",
                refdoc=app.env.docname,
            )
            only = addnodes.only(expr="html")
            only += xref
            signode += only


def _missing_reference(app, env, node, contnode):
    """Turn our pending_xref into a relative link once the builder is known."""
    if node.get("reftype") != "matsource":
        return None
    try:
        uri = app.builder.get_relative_uri(node["refdoc"], node["reftarget"])
    except NoUri:
        return contnode
    if node.get("refid"):
        uri += "#" + node["refid"]
    return nodes.reference("", "", contnode, refuri=uri, internal=True)


def _collect_pages(app):
    """Emit one highlighted HTML page per .m file."""
    highlighter = app.builder.highlighter
    for rel in sorted({rel for paths in _INDEX.values() for rel in paths}):
        try:
            code = _read(rel)
        except OSError:
            continue
        body = highlighter.highlight_block(code, "matlab", linenos=False, linespans="L")
        title_text = rel.split(".m")[0].replace("/", ".").replace("+", "")
        title = nodes.Text(title_text).astext()
        context = {"parents": [], "title": title, "body": f"<h1>{title}</h1>\n{body}"}
        yield (_pagename(app, rel), context, "page.html")


def setup(app):
    app.add_config_value("matlab_source_subdir", "_matlabsrc", "html", types=(str,))
    app.connect("builder-inited", _build_index)
    app.connect("doctree-read", _add_source_links)
    app.connect("missing-reference", _missing_reference)
    app.connect("html-collect-pages", _collect_pages)
    return {"version": "3.0", "parallel_read_safe": True}
